import{_ as i,l,o as a,c as n,v as t,p as d,x as o,d as c,i as s,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"类型推导直觉","description":"","frontmatter":{"title":"类型推导直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/type-inference.md","filePath":"cs/type-inference.md","lastUpdated":1789023840000}'),h={name:"cs/type-inference.md"};function m(_,e,u,f,A,E){const r=l("Mermaid");return a(),n("div",null,[e[1]||(e[1]=t('<h1 id="类型推导直觉" tabindex="-1">类型推导直觉 <a class="header-anchor" href="#类型推导直觉" aria-label="Permalink to &quot;类型推导直觉&quot;">​</a></h1><div class="epigraph"><p>声明可省略类型时，从使用处列出等式，用合一解出最一般类型；检查是推导在注解已写满时的特例。</p><footer>—— 据 Hindley, The Principal Type-Scheme of an Object in Combinatory Logic, 1969；Milner, A Theory of Type Polymorphism in Programming, 1978；龙书第 6 章整理</footer></div><p>上一课<a href="/cs/typecheck">类型检查</a>在声明带着类型、表达式综合再比对的规则下拒绝或放行。本课不重写算术规则。缺口是<strong>注解不全</strong>：<code>let</code> 绑定没有写类型，要从 <code>x+1</code> 与 <code>f(x)</code> 反推 \\(x\\) 的类型。主干只要直觉：类型变量、等式、合一；Hindley–Milner 的 let 多态点名，不把 occurs check 证成论文。后课重载与强制在已解出的类型上再选声明。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>检查：已知 \\(e\\) 应有类型 \\(\\tau\\)，递归验证。推导：未知 \\(\\tau\\)，生成 \\(\\tau=\\mathrm{int}\\) 或 \\(\\tau_1\\to\\tau_2\\) 一类约束，解方程组。合一：两个类型表达式最一般的公共实例。失败则类型错误（无限类型、\\(int\\) 与 \\(bool\\) 冲突）。缺口是约束，不是再定义结构等价。</p><p>函数参数：引入新鲜类型变量，体里收集约束，返回类型也是变量或由 <code>return</code> 等式钉死。多态：在 <code>let</code> 处推广未被环境约束的变量，使用处再实例化。这是 Milner 的 let 多态；一等泛型更后，本课不启用。</p><h3 id="推导不是「运行时猜」" tabindex="-1">推导不是「运行时猜」 <a class="header-anchor" href="#推导不是「运行时猜」" aria-label="Permalink to &quot;推导不是「运行时猜」&quot;">​</a></h3><p>仍是编译期。解不出来就拒绝，不生成带 tag 的解释器。动态类型语言不做本课这套等式。</p><p><span class="marginnote">Hindley 1969；Milner 1978（J.CSS）与 Algorithm W。Cardelli 综述可对照上一课。龙书以检查为主，推导作扩展。Appel 的函数式章用合一。本课不把 System F 写进主干。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>遍历 AST，为无注解节点分配类型变量。对每个运算符发出等式（两操作数合一、结果为规定类型）。<code>Unify</code> 带替换。结束时每个节点得到基类型或带量化的方案。</p>',11)),(a(),d(p,null,{default:o(()=>[s(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20AST%5B%22%E9%83%A8%E5%88%86%E6%B3%A8%E8%A7%A3%E7%9A%84%20AST%22%5D%20--%3E%20VAR%5B%22%E7%B1%BB%E5%9E%8B%E5%8F%98%E9%87%8F%22%5D%0A%20%20VAR%20--%3E%20EQ%5B%22%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20EQ%20--%3E%20UNI%5B%22%E5%90%88%E4%B8%80%22%5D%0A%20%20UNI%20--%3E%20TAU%5B%22%E4%B8%BB%E7%B1%BB%E5%9E%8B%20%2F%20%E9%94%99%E8%AF%AF%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>有注解则当等式的一侧已是具体类型，退化成上一课的检查。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>最一般类型（principal type）使同一 <code>id</code> 的推导结果可被所有合法使用共享。过早实例化会把 <code>id</code> 钉死成 <code>int-&gt;int</code> 而不能用于 <code>bool</code>。let 多态的规则就是为了这个。重载不在合一里：<code>+</code> 有多套规则，下一课先选再合一，或生成有限候选。</p><p>发生检查：变量不能合一到含自身的项，否则无限类型。点名即可。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写完整 W 伪代码，不做效果系统、生命周期。子类型合一更复杂（宽化），点名留给强制课。后课默认：缺注解可用约束求解；多声明同名或隐式转换是下一缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>推导 = 类型变量 + 合一；检查是约束已写满。</li><li>let 多态在绑定处推广；本课不引入 System F。</li><li>重载与强制不在合一内部解决。</li><li>出处：Hindley, 1969；Milner, 1978；龙书第 6 章。</li></ul>',8))])}const b=i(h,[["render",m]]);export{B as __pageData,b as default};
